// display-only: state vs a plain variable
let count = 0;                             // resets on every render — amnesia
const [likes, setLikes] = useState(0);     // remembered by React

// display-only: the useState pair
const [name, setName] = useState('Roli');
//  name    → the current value ('Roli')
//  setName → the function that updates it

// display-only: setter triggers re-render
function Counter() {
  const [count, setCount] = useState(0);
  return (
    <button onClick={() => setCount(count + 1)}>
      Clicked {count} times
    </button>
  );
}

// display-only: initial value runs once
const [score, setScore] = useState(100);
// first render: score is 100
// after setScore(150) + re-render: score is 150, NOT reset to 100

// display-only: independent state
function App() {
  return (
    <div>
      <Counter />  {/* its own count */}
      <Counter />  {/* a different count */}
    </div>
  );
}

